from pathlib import Path
import importlib.util,ast,json,hashlib
from collections import Counter
P=Path('work/deg10/continuation_20261031b/M3N27')
spec=importlib.util.spec_from_file_location('cc',P/'inputs/cusp_conditions_relative.py');cc=importlib.util.module_from_spec(spec);spec.loader.exec_module(cc)
c=cc.compute(3,27,2,6);assert Counter(c['closed_cusp_degrees'])=={1:27,3:6,9:3}
assert pow(4,9,27)==1 and all(pow(4,e,27)!=1 for e in[1,3])
# The relative cusp Galois group has order phi(27)/phi(3)=9 and is generated by Frobenius4.
a=ast.literal_eval((P/'frob_preflight.m').read_text().replace('[*','[').replace('*]',']'));assert a[0]==46
from sage.all import GammaH,ModularSymbols,QQ,identity_matrix,ZZ
rows=ast.literal_eval((P/"torsion_gcd.m").read_text().replace("[*","[").replace("*]","]"));number=next(r[2] for r in rows if r[0]==37)
S=ModularSymbols(GammaH(81,[28]),2,sign=1).cuspidal_subspace();assert S.dimension()==46
T=S.hecke_operator(37).matrix();D=S.diamond_bracket_operator(37).matrix();I=identity_matrix(QQ,46);native=ZZ((I-T+37*D).det());assert native==number and number%2==1
q4=next(r for r in a[1] if r[0]==2);nc=[q4[2][d-1]-c['closed_cusp_degrees'].count(d) for d in range(1,6)];assert nc==[0,0,0,0,162]
result={'status':'PASS','geometric_cusps':72,'global_cusp_signature':{'1':27,'3':6,'9':3},'F4_cusp_signature':dict(Counter(c['closed_cusp_degrees'])),'Frobenius4_order_mod27':9,'entire_relative_cusp_Galois_group_generated':True,'all_F4_closed_cusp_blocks_lift_globally':True,'Jacobian_F37_order':number,'Jacobian_F37_order_odd':True,'NC_closed_counts_F4':nc,'Tate_cusp_enumeration':c}
(P/'cusp_parity.json').write_text(json.dumps(result,indent=2)+'\n');print('D31B_M327_CUSP_PARITY_COMPLETE',number,nc)
